"""Build local low jab report and impact previews without changing source assets."""
from pathlib import Path
from PIL import Image
import json,csv,html
ROOT=Path(__file__).resolve().parents[2];REPORT=ROOT/'demo-moves/reports';POSES=REPORT/'light-kick-low-poses';POSES.mkdir(exist_ok=True)
read=lambda p:json.loads((ROOT/p).read_text(encoding='utf-8-sig'))
manifest=read('animation/light-kick-low-manifest.json');timing=read('animation/light-kick-low-timing.json');records=[];rows=[]
for item in sorted(manifest['items'],key=lambda i:i['character'].lower()):
 t=next(t for t in timing['items'] if t['character']==item['character']);assert t['sourceSheetId']==item['sourceSheetId']
 peak=t['impactFrame'];count=item['frames'];slug=item['character'].lower();atlas=read(item['atlas']);f=atlas['frames'][str(peak)]['frame']
 image=Image.open(ROOT/item['png']).convert('RGBA');image.crop((f['x'],f['y'],f['x']+512,f['y']+512)).save(POSES/(slug+'.png'))
 before=timing['impactMs']/peak;after=(timing['durationMs']-timing['impactMs'])/(count-peak)
 records.append([item['character'],count,peak+1,t['impactSourceFrame'],300,600,round(before,6),round(after,6),item['sourceSheetId'],item['sourceStart'],item['sourceEnd'],'forward'])
 name=html.escape(item['character'])
 rows.append(f'<tr><th>{name}</th><td><img src="light-kick-low-poses/{slug}.png" width="128" height="128" alt="Impatto basso di {name}" loading="lazy"></td><td>{peak+1} / {count}</td><td>300 ms</td><td>600 ms</td><td>{before:.2f} / {after:.2f} ms</td><td>{item["sourceStart"]}–{item["sourceEnd"]}</td><td>{"Trimmed" if item["trimmed"] else "Completa"}</td></tr>')
with (REPORT/'light-kick-low-timing.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.writer(f);w.writerow(['Personaggio','Frame totali','Frame impatto da 1','Frame impatto sorgente da 0','Impatto ms','Totale ms','Durata frame prima ms','Durata frame dopo ms','Source sheet ID','Source start','Source end','Playback']);w.writerows(records)
page='''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Calcio leggero basso · Timing</title><style>body{font:15px/1.5 system-ui;background:#141815;color:#eff3eb;padding:24px;margin:0}main{max-width:1300px;margin:auto}a{color:#ceef80}p{max-width:950px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #3b493c}thead{background:#273329}img{background:#cbd3ca;border-radius:8px;image-rendering:pixelated;object-fit:contain}</style><main><a href="../mosse.html?move=light-kick-low">Apri la mossa nella demo</a><h1>Calcio leggero basso · Timing</h1><p>Aggiornamento 23 novembre 2026. Nove personaggi. Stesso timing del Calcio leggero: la posa scelta di massima estensione inizia a <b>300 ms</b> e il ciclo termina a <b>600 ms</b> a velocità 1×. Durate variabili prima e dopo il marcatore, senza cambiare ordine o pixel dei frame.</p><p>Gli spritesheet contengono già il recupero in guardia accovacciata e sono eseguiti solo in avanti. Loop attivo per default. Versioni trimmed selezionate quando presenti; per Oscar è esportato una sola volta l’intervallo salvato 0–17 del foglio da 30 frame. Le pose estese adiacenti possono differire di pochi pixel: il report mostra il primo frame della massima estensione osservata.</p><p>175 celle RGBA confrontate con i PNG sorgente dopo l’esportazione: nessuna modifica a dimensioni, margini interni o scala. Nessuna generazione AutoSprite, 0 crediti.</p><p>Controllo alpha: esaminati i 175 fotogrammi selezionati, con confronto visivo delle pose e dei casi sospetti su fondo bianco, nero e canale alpha. Non sono emersi buchi evidenti nei corpi analoghi a quelli riscontrati sui pugni di Marsan; bordi sfumati e spazi naturali tra gli arti sono conservati. <a href="light-kick-low-alpha.png">Confronto alpha dei nove personaggi</a>.</p><p><a href="light-kick-low-timing.csv" download>Scarica i timing CSV</a></p><div class="table-wrap"><table><thead><tr><th>Personaggio</th><th>Impatto</th><th>Frame (da 1)</th><th>Impatto</th><th>Totale</th><th>Durata frame prima / dopo</th><th>Intervallo sorgente (da 0)</th><th>Versione</th></tr></thead><tbody>'''+''.join(rows)+'</tbody></table></div></main></html>'
(REPORT/'light-kick-low-timing.html').write_text(page,encoding='utf-8');print('Report Light Kick Low: nove pose e CSV.')
